/**
 * Install Code
 */
class ips_plugins_setup_install
{
	/**
	 * ...
	 *
	 * @return	array	If returns TRUE, upgrader will proceed to next step. If it returns any other value, it will set this as the value of the 'extra' GET parameter and rerun this step (useful for loops)
	 */
	public function step1()
	{
        if(\IPS\Db::i()->checkForColumn('core_members','is_tapatalk_member') == false)
        {
            \IPS\Db::i()->addColumn( 'core_members', array(
            'name'		=> 'is_tapatalk_member',
            'type'		=> 'BIT',
            'length'	=> 1,
            'null'		=> FALSE,
            'default'	=> 0,
            'comment'	=> 'If 1, the user used Tapatalk and should receive Tapatalk Push Notifications'
            ) );
        }
		return TRUE;
	}

	// You can create as many additional methods (step2, step3, etc.) as is necessary.
	// Each step will be executed in a new HTTP request
}
